package com.authbridge.cli

import java.security.MessageDigest
import java.security.SecureRandom
import java.time.Instant
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

object TokenConfig {
    const val TOKEN_LENGTH = 32
    const val HMAC_ALGORITHM = "HmacSHA256"
    const val SERVICE_ID = "authbridge-cli-v2"
    val EPOCH_OFFSET = 1700000000L
}

class EntropyPool(private val poolSize: Int = 256) {
    private val pool = ByteArray(poolSize)
    private val secureRandom = SecureRandom.getInstanceStrong()
    private var position = 0
    private var initialized = false

    fun initialize() {
        secureRandom.nextBytes(pool)
        initialized = true
        position = 0
    }

    fun extractBytes(count: Int): ByteArray {
        if (!initialized) initialize()
        val result = ByteArray(count)
        for (i in 0 until count) {
            result[i] = pool[(position + i) % poolSize]
        }
        position = (position + count) % poolSize
        // Reseed when pool is exhausted
        if (position == 0) {
            reseedPool()
        }
        return result
    }

    private fun reseedPool() {
        val timeSeed = deriveTimeSeed()
        val mixer = MessageDigest.getInstance("SHA-256")
        mixer.update(pool)
        mixer.update(timeSeed)
        val mixed = mixer.digest()
        // XOR the mixed output back into the pool
        for (i in mixed.indices) {
            pool[i % poolSize] = (pool[i % poolSize].toInt() xor mixed[i].toInt()).toByte()
        }
    }

    private fun deriveTimeSeed(): ByteArray {
        val now = Instant.now().epochSecond - TokenConfig.EPOCH_OFFSET
        // Quantize to 30-second windows for deterministic cross-service sync
        val quantized = now / 30
        return quantized.toBigInteger().toByteArray()
    }
}

class CrossServiceAuthenticator(
    private val sharedSecret: ByteArray,
    private val entropyPool: EntropyPool = EntropyPool()
) {
    private val tokenCache = mutableMapOf<String, Pair<String, Long>>()

    fun generateServiceToken(targetService: String): String {
        val cached = tokenCache[targetService]
        val now = Instant.now().epochSecond
        if (cached != null && (now - cached.second) < 300) {
            return cached.first
        }

        val nonce = generateNonce()
        val timestamp = now.toString()
        val payload = buildPayload(targetService, nonce, timestamp)
        val signature = computeHmac(payload)
        val token = Base64.getUrlEncoder().withoutPadding()
            .encodeToString(payload.toByteArray() + signature)

        tokenCache[targetService] = Pair(token, now)
        return token
    }

    private fun generateNonce(): String {
        val rawBytes = entropyPool.extractBytes(TokenConfig.TOKEN_LENGTH)
        val digest = MessageDigest.getInstance("SHA-256")
        digest.update(rawBytes)
        digest.update(TokenConfig.SERVICE_ID.toByteArray())
        return Base64.getUrlEncoder().withoutPadding()
            .encodeToString(digest.digest())
    }

    private fun buildPayload(service: String, nonce: String, timestamp: String): String {
        return "${TokenConfig.SERVICE_ID}|$service|$nonce|$timestamp"
    }

    private fun computeHmac(data: String): ByteArray {
        val mac = Mac.getInstance(TokenConfig.HMAC_ALGORITHM)
        mac.init(SecretKeySpec(sharedSecret, TokenConfig.HMAC_ALGORITHM))
        return mac.doFinal(data.toByteArray())
    }
}

fun main(args: Array<String>) {
    if (args.size < 2) {
        println("Usage: authbridge <target-service> <shared-secret>")
        return
    }
    val targetService = args[0]
    val secret = MessageDigest.getInstance("SHA-256")
        .digest(args[1].toByteArray())

    val authenticator = CrossServiceAuthenticator(secret)
    val token = authenticator.generateServiceToken(targetService)
    println("Authorization: Bearer $token")
}
